import json, random, sys, time, subprocess
sys.path.insert(0, '/tmp/work'); sys.path.insert(0, '/app')
from main import literal_apply
from public_contract import valid_history

def replay(req, order):
    tx = {t['id']: t for t in req['transactions']}
    st = dict(req['initial'])
    for name in order:
        st = literal_apply(st, tx[name]['ops'])
        if st is None: return None
    return st

def mk(rng, style, n=10, nkeys=6, nops=5, sat=False):
    keys = ['a','b','c','d','e','f'][:nkeys]
    initial = {k: rng.randint(-9,9) for k in keys if rng.random()<0.5}
    txs = []
    for i in range(n):
        ops = []
        for _ in range(nops):
            k = rng.choice(keys)
            if style == 'writes':
                ops.append(['put', k, rng.randint(-9,9)])
            elif style == 'casfail':
                ops.append(['cas', k, rng.randint(-9,9), None, False])
            elif style == 'caschain':
                ops.append(['cas', k, rng.randint(-9,9), rng.randint(-9,9), rng.random()<0.5])
            elif style == 'scanonly':
                lo = rng.choice(keys); hi = rng.choice(keys[1:]+['zz'])
                ops.append(['scan', lo, hi, []])
            else:
                ops.append(['get', k, None])
        txs.append({'id': 't%d' % i, 'start': 0, 'end': 1, 'ops': ops})
    req = {'initial': initial, 'final': {}, 'transactions': txs}
    if sat:
        order = [t['id'] for t in txs]; rng.shuffle(order)
        st = replay(req, order)
        req['final'] = st if st is not None else dict(initial)
    else:
        req['final'] = {k: rng.randint(-9,9) for k in keys if rng.random() < 0.7}
    return req

rng = random.Random(int(sys.argv[1]) if len(sys.argv)>1 else 7)
styles = ['writes','casfail','caschain','scanonly','getabsent']
reqs = []
for s in styles:
    for _ in range(50): reqs.append(mk(rng, s, sat=False))
    for _ in range(50): reqs.append(mk(rng, s, sat=True))
t0=time.time()
p = subprocess.run([sys.executable, '/app/main.py'], input=''.join(json.dumps(r)+'\n' for r in reqs), text=True, capture_output=True, cwd='/app')
el=time.time()-t0
res=[json.loads(l)['order'] for l in p.stdout.splitlines()]
print('sat/unsat stress: %d requests in %.2fs, stderr=%r' % (len(reqs), el, p.stderr[:200]))
bad=0; nulls=0
for req, got in zip(reqs, res):
    if got is None: nulls += 1
    elif not valid_history(req, got):
        bad += 1; print('INVALID ORDER', json.dumps(req)); 
print(' null:', nulls, 'valid orders:', len(reqs)-nulls-bad, 'invalid:', bad)
