import json, random, sys, time, statistics
sys.path.insert(0,'/tmp/work'); sys.path.insert(0,'/app')
from main import solve, literal_apply, backward_search, parse_request
from public_contract import valid_history

def replay(req, order):
    tx={t['id']:t for t in req['transactions']}
    st=dict(req['initial'])
    for name in order:
        st=literal_apply(st,tx[name]['ops'])
        if st is None: return None
    return st

KEYS=['a','b','c','d','e','f']
def gen(rng, n=10, nkeys=6, nops=5, overlap=True, span=12, finalmode='replay'):
    keys=sorted(rng.sample(KEYS,nkeys))
    initial={k:rng.randint(-9,9) for k in keys if rng.random()<0.6}
    txs=[]
    for i in range(n):
        if overlap: s,e=0,1
        else:
            s=rng.randint(0,span-2); e=rng.randint(s+1,span)
        ops=[]
        for _ in range(nops):
            k=rng.choice(keys)
            c=rng.random()
            if c<0.35: ops.append(['put',k,rng.randint(-9,9)])
