"""Truthful history generator: records what a real concurrent run would see."""
KEYPOOL = ['a','b','c','d','e','f','g','h','ab','bb','ba','aa']

def truthful(rng, n=10, nkeys=6, nops=5, overlap=True, span=12, tight=False):
    keys = sorted(rng.sample(KEYPOOL, nkeys))
    initial = {k: rng.randint(-9, 9) for k in keys if rng.random() < 0.6}
    if overlap:
        ivs = [(0, 1)] * n
    elif tight:
        ivs = [(i, i + 2) for i in range(n)]
    else:
        ivs = [None] * n
        for i in range(n):
            s = rng.randint(0, span - 2); ivs[i] = (s, rng.randint(s + 1, span))
    rem = list(range(n)); order = []
    while rem:                       # a random real-time consistent order
        ready = [t for t in rem if all(not (ivs[t][1] <= ivs[u][0]) for u in rem if u != t)]
        t = rng.choice(ready); rem.remove(t); order.append(t)
    state = dict(initial); txs = {}
    for t in order:
        st = dict(state); ops = []
        for _ in range(nops):
            k = rng.choice(keys); c = rng.random()
            if c < 0.30:
                v = rng.randint(-9, 9); ops.append(['put', k, v]); st[k] = v
            elif c < 0.45:
                ops.append(['del', k]); st.pop(k, None)
            elif c < 0.70:
                old = st.get(k)
                new = None if rng.random() < 0.2 else rng.randint(-9, 9)
                ops.append(['cas', k, old, new, True])
                if new is None: st.pop(k, None)
                else: st[k] = new
            elif c < 0.88:
                ops.append(['get', k, st.get(k)])
            else:
                lo = rng.choice(keys)
                hi = rng.choice([x for x in keys if x > lo] or ['zz'])
                ops.append(['scan', lo, hi, sorted([[k2, v] for k2, v in st.items() if lo <= k2 < hi])])
        state = st
        txs[t] = {'id': 't%d' % t, 'start': ivs[t][0], 'end': ivs[t][1], 'ops': ops}
    return {'initial': initial, 'final': dict(state),
            'transactions': [txs[t] for t in sorted(txs)]}, ['t%d' % t for t in order]
